'use client'

import { useEffect, useState } from 'react'
import { createClient } from '@/lib/supabase'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Loader2 } from 'lucide-react'

// Define interfaces for type safety
interface PitData {
    id: string
    team_number: number
    robot_weight: number
    drive_train_type: string
    collection_speed: string
    shooting_speed: string
    super_charged: boolean
    movement_abilities: string[]
    comments: string
}

export default function PitScoutingList() {
    const [pitData, setPitData] = useState<PitData[]>([])
    const [loading, setLoading] = useState(true)
    const [selectedTeam, setSelectedTeam] = useState<string>('all')

    const supabase = createClient()

    useEffect(() => {
        async function fetchData() {
            const { data, error } = await supabase
                .from('pit_scouting')
                .select('*')
                .order('team_number', { ascending: true })

            if (error) {
                console.error('Error fetching pit data:', error)
            } else {
                setPitData(data || [])
            }
            setLoading(false)
        }

        fetchData()
    }, [])

    const filteredData = selectedTeam === 'all'
        ? pitData
        : pitData.filter(d => d.team_number.toString() === selectedTeam)

    if (loading) {
        return <div className="flex justify-center p-8"><Loader2 className="h-8 w-8 animate-spin" /></div>
    }

    return (
        <div className="space-y-4">
            <div className="flex items-center gap-4">
                <h2 className="text-xl font-bold">Pit Scouting Data</h2>
                <Select value={selectedTeam} onValueChange={(val) => setSelectedTeam(val || 'all')}>
                    <SelectTrigger className="w-[180px]">
                        <SelectValue placeholder="Filter by Team" />
                    </SelectTrigger>
                    <SelectContent>
                        <SelectItem value="all">All Teams</SelectItem>
                        {Array.from(new Set(pitData.map(d => d.team_number))).map((teamNum) => (
                            <SelectItem key={teamNum} value={teamNum.toString()}>Team {teamNum}</SelectItem>
                        ))}
                    </SelectContent>
                </Select>
            </div>

            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                {filteredData.map((robot) => (
                    <Card key={robot.id} className="overflow-hidden">
                        <CardHeader className="bg-muted/50 pb-2">
                            <div className="flex justify-between items-center">
                                <CardTitle className="text-2xl">Team {robot.team_number}</CardTitle>
                                {robot.super_charged && (
                                    <span className="bg-yellow-400 text-yellow-900 text-xs font-bold px-2 py-1 rounded-full uppercase tracking-wide">
                                        Super Charged
                                    </span>
                                )}
                            </div>
                        </CardHeader>
                        <CardContent className="pt-4  space-y-2 text-sm">
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">Drive Train:</span>
                                <span className="font-medium">{robot.drive_train_type}</span>
                            </div>
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">Weight:</span>
                                <span className="font-medium">{robot.robot_weight} lbs</span>
                            </div>
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">Collection:</span>
                                <span className="font-medium">{robot.collection_speed}</span>
                            </div>
                            <div className="flex justify-between">
                                <span className="text-muted-foreground">Shooting:</span>
                                <span className="font-medium">{robot.shooting_speed}</span>
                            </div>
                            <div className="pt-2 border-t">
                                <span className="text-muted-foreground block mb-1">Abilities:</span>
                                <div className="flex flex-wrap gap-1">
                                    {robot.movement_abilities && robot.movement_abilities.map((ability, idx) => (
                                        <span key={idx} className="bg-primary/10 text-primary px-2 py-0.5 rounded text-xs">
                                            {ability}
                                        </span>
                                    ))}
                                </div>
                            </div>
                        </CardContent>
                    </Card>
                ))}
                {filteredData.length === 0 && (
                    <div className="col-span-full text-center p-8 text-muted-foreground">
                        No pit scouting data found.
                    </div>
                )}
            </div>
        </div>
    )
}
