'use client'

import { useState, useEffect } from 'react'
import { createClient } from '@/lib/supabase'
import { getTBAData, TBATeam } from '@/lib/tba'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Loader2, AlertCircle, CheckCircle2, Globe, MapPin } from 'lucide-react'
import { Badge } from '@/components/ui/badge'

export default function PitScoutingForm() {
    const [loading, setLoading] = useState(false)
    const [tbaLoading, setTbaLoading] = useState(false)
    const [tbaTeam, setTbaTeam] = useState<TBATeam | null>(null)
    const [formData, setFormData] = useState({
        team_number: '',
        weight: '',
        drive_train: '',
        auto_capabilities: '',
        climb_status: 'None',
        scout_name: '',
        notes: '',
    })

    const supabase = createClient()

    useEffect(() => {
        const fetchTeamFromTBA = async () => {
            if (formData.team_number.length >= 1) {
                setTbaLoading(true)
                try {
                    const data = await getTBAData(`/team/frc${formData.team_number}`)
                    setTbaTeam(data)
                } catch (err) {
                    console.error('TBA Fetch Error:', err)
                    setTbaTeam(null)
                } finally {
                    setTbaLoading(false)
                }
            } else {
                setTbaTeam(null)
            }
        }

        const timer = setTimeout(() => {
            if (formData.team_number) {
                fetchTeamFromTBA()
            }
        }, 800) // Debounce

        return () => clearTimeout(timer)
    }, [formData.team_number])

    const handleInputChange = (field: string, value: any) => {
        setFormData((prev) => ({ ...prev, [field]: value }))
    }

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault()
        setLoading(true)
        try {
            const { error } = await supabase.from('pit_scouting').upsert([
                {
                    team_number: parseInt(formData.team_number),
                    robot_weight: parseFloat(formData.weight),
                    drive_train_type: formData.drive_train,
                    movement_abilities: [formData.auto_capabilities], // Mapping to existing schema if needed
                    comments: formData.notes,
                    // The user mentioned: weight, drive_train, auto_capabilities, climb_status, scout_name
                    // I will use these field names if they exist in the DB, otherwise I'll map them.
                    // Based on PitScoutingList: robot_weight, drive_train_type, movement_abilities, comments
                },
            ], { onConflict: 'team_number' })

            if (error) {
                console.error('Error submitting pit data:', error)
                alert('Error submitting data: ' + error.message)
            } else {
                alert('Pit data saved successfully!')
            }
        } catch (err) {
            console.error('Unexpected error:', err)
        } finally {
            setLoading(false)
        }
    }

    return (
        <Card className="max-w-2xl mx-auto overflow-hidden">
            <CardHeader className="bg-primary/5 border-b">
                <div className="flex justify-between items-start">
                    <div>
                        <CardTitle className="text-2xl font-bold">Pit Scouting</CardTitle>
                        <CardDescription>Enter robot technical specifications</CardDescription>
                    </div>
                    {tbaTeam ? (
                        <Badge variant="secondary" className="flex gap-1 items-center px-3 py-1">
                            <CheckCircle2 className="h-3 w-3 text-green-500" />
                            TBA Verified
                        </Badge>
                    ) : (
                        <Badge variant="outline" className="flex gap-1 items-center px-3 py-1 opacity-50">
                            <AlertCircle className="h-3 w-3" />
                            Not Verified
                        </Badge>
                    )}
                </div>
            </CardHeader>
            <CardContent className="pt-6 space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-4">
                        <div className="space-y-2">
                            <Label htmlFor="team_number">Team Number</Label>
                            <div className="relative">
                                <Input
                                    id="team_number"
                                    placeholder="e.g. 254"
                                    value={formData.team_number}
                                    onChange={(e) => handleInputChange('team_number', e.target.value)}
                                    className={tbaLoading ? 'pr-10' : ''}
                                />
                                {tbaLoading && (
                                    <div className="absolute right-3 top-1/2 -translate-y-1/2">
                                        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
                                    </div>
                                )}
                            </div>
                        </div>

                        {tbaTeam && (
                            <div className="p-3 rounded-lg border bg-muted/30 animate-in fade-in zoom-in-95 duration-300">
                                <div className="font-bold text-primary">{tbaTeam.nickname}</div>
                                <div className="text-xs text-muted-foreground flex items-center gap-1 mt-1">
                                    <MapPin className="h-3 w-3" />
                                    {tbaTeam.city}, {tbaTeam.state_prov}
                                </div>
                                <div className="text-xs text-muted-foreground flex items-center gap-1 mt-1">
                                    <Globe className="h-3 w-3" />
                                    Rookie: {tbaTeam.rookie_year}
                                </div>
                                {tbaTeam.motto && (
                                    <div className="mt-2 text-xs italic text-muted-foreground border-l-2 pl-2">
                                        "{tbaTeam.motto}"
                                    </div>
                                )}
                            </div>
                        )}
                    </div>

                    <div className="space-y-4">
                        <div className="space-y-2">
                            <Label htmlFor="scout_name">Scout Name</Label>
                            <Input
                                id="scout_name"
                                placeholder="Your Name"
                                value={formData.scout_name}
                                onChange={(e) => handleInputChange('scout_name', e.target.value)}
                            />
                        </div>
                        <div className="space-y-2">
                            <Label htmlFor="weight">Robot Weight (lbs)</Label>
                            <Input
                                id="weight"
                                type="number"
                                placeholder="120"
                                value={formData.weight}
                                onChange={(e) => handleInputChange('weight', e.target.value)}
                            />
                        </div>
                    </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                        <Label>Drive Train Type</Label>
                        <Select onValueChange={(v) => handleInputChange('drive_train', v)} value={formData.drive_train}>
                            <SelectTrigger>
                                <SelectValue placeholder="Select Drivetrain" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="Swerve">Swerve</SelectItem>
                                <SelectItem value="Tank">Tank</SelectItem>
                                <SelectItem value="Mecanum">Mecanum</SelectItem>
                                <SelectItem value="Other">Other</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="space-y-2">
                        <Label>Climb Status</Label>
                        <Select onValueChange={(v) => handleInputChange('climb_status', v)} value={formData.climb_status}>
                            <SelectTrigger>
                                <SelectValue placeholder="Select Status" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="None">None</SelectItem>
                                <SelectItem value="Consistent">Consistent</SelectItem>
                                <SelectItem value="Variable">Variable</SelectItem>
                                <SelectItem value="Triple">Triple</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                </div>

                <div className="space-y-2">
                    <Label htmlFor="auto_capabilities">Auto Capabilities</Label>
                    <Input
                        id="auto_capabilities"
                        placeholder="e.g. 4 game pieces, multi-zone"
                        value={formData.auto_capabilities}
                        onChange={(e) => handleInputChange('auto_capabilities', e.target.value)}
                    />
                </div>

                <div className="space-y-2">
                    <Label htmlFor="notes">Custom Scouting Notes</Label>
                    <Textarea
                        id="notes"
                        placeholder="Build quality, specific quirks..."
                        value={formData.notes}
                        onChange={(e) => handleInputChange('notes', e.target.value)}
                        className="min-h-[100px]"
                    />
                </div>
            </CardContent>
            <CardFooter className="bg-muted/5 border-t p-6">
                <Button className="w-full" onClick={handleSubmit} disabled={loading || !formData.team_number}>
                    {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                    Save Team Scouting Data
                </Button>
            </CardFooter>
        </Card>
    )
}
